def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to separate build metadata
        parts = version.split('+')
        core = parts[0]

        # Split by '-' to separate pre-release
        if '-' in core:
            main_part, prerelease = core.split('-', 1)
            prerelease_identifiers = prerelease.split('.')
        else:
            main_part = core
            prerelease_identifiers = None

        # Parse MAJOR.MINOR.PATCH
        version_parts = main_part.split('.')
        major = int(version_parts[0])
        minor = int(version_parts[1])
        patch = int(version_parts[2])

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(prerelease_identifiers):
        # If no pre-release, return a tuple that sorts after any pre-release
        if prerelease_identifiers is None:
            return (1,)  # Sorts after (0, ...)

        # Build a comparable tuple for pre-release identifiers
        identifiers = []
        for identifier in prerelease_identifiers:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                identifiers.append((0, int(identifier)))
            else:
                # Non-digit identifiers: (1, string_value)
                identifiers.append((1, identifier))

        return (0, tuple(identifiers))

    # Parse all versions with their original index
    parsed = []
    for idx, version in enumerate(versions):
        major, minor, patch, prerelease = parse_version(version)
        key = (major, minor, patch, prerelease_key(prerelease))
        parsed.append((key, idx, version))

    # Sort by the key, maintaining stable sort (original order for equal keys)
    parsed.sort(key=lambda x: x[0])

    # Return sorted version strings
    return [v[2] for v in parsed]

